};

enum cusolverMgProfileCallbackId {
    cusolverMg_TRACE_CBID_cusolverMgCreate = 0,
    cusolverMg_TRACE_CBID_cusolverMgCreateDeviceGrid = 1,
    cusolverMg_TRACE_CBID_cusolverMgCreateMatrixDesc = 2,
    cusolverMg_TRACE_CBID_cusolverMgDestroy = 3,
    cusolverMg_TRACE_CBID_cusolverMgDestroyGrid = 4,
